// Serves the pre-built Markdown variant of a page (site/**/*.md, generated by build.js)
// to AI agents: requests with `Accept: text/markdown`, or from known AI crawler/agent
// User-Agents. Browsers and search-engine crawlers (Googlebot, Bingbot) get the HTML.
import type { Config, Context } from "https://edge.netlify.com";

const AI_AGENTS =
  /GPTBot|ChatGPT-User|OAI-SearchBot|ClaudeBot|Claude-User|Claude-SearchBot|Claude-Web|anthropic-ai|PerplexityBot|Perplexity-User|CCBot|cohere-ai|Google-Extended|Amazonbot|Applebot-Extended|Meta-ExternalAgent|DuckAssistBot|MistralAI-User/i;

function mdPath(pathname: string): string | null {
  if (pathname.endsWith("/")) return pathname + "index.md";
  if (pathname.endsWith(".html")) return pathname.slice(0, -5) + ".md";
  if (!/\.[a-z0-9]+$/i.test(pathname)) return pathname + ".md"; // pretty URL: /about
  return null;
}

export default async (request: Request, context: Context) => {
  const accept = request.headers.get("accept") ?? "";
  const ua = request.headers.get("user-agent") ?? "";
  const wantsMarkdown = /\btext\/markdown\b/i.test(accept) || AI_AGENTS.test(ua);
  if (!wantsMarkdown || request.method !== "GET") return context.next();

  const url = new URL(request.url);
  const md = mdPath(url.pathname);
  if (!md) return context.next();

  const res = await fetch(new URL(md, url));
  if (!res.ok) return context.next();

  return new Response(res.body, {
    status: 200,
    headers: {
      "content-type": "text/markdown; charset=utf-8",
      "vary": "Accept, User-Agent",
      "cache-control": "public, max-age=0, must-revalidate",
      "link": `<${url.origin}${url.pathname}>; rel="canonical"`,
      "x-robots-tag": "noindex",
    },
  });
};

export const config: Config = {
  path: ["/", "/*.html", "/sv/", "/da/", "/no/", "/fi/", "/de/", "/about", "/team", "/companies", "/news", "/contact", "/why-publix"],
};
